const items = $input.all();
if (items.length === 0 || items[0].json.title === null) {
  return [{ json: { text: "📂 <b>ПОСЛЕДНИЕ ВСТРЕЧИ</b>\n━━━━━━━━━━━━━━━━━━━━━━\nВ базе данных пока нет сохраненных встреч." } }];
}
let text = "📂 <b>ПОСЛЕДНИЕ ВСТРЕЧИ</b>\n━━━━━━━━━━━━━━━━━━━━━━\n\n";
items.forEach((item, index) => {
  const date = new Date(item.json.transcribed_at).toLocaleString('ru-RU', { timeZone: 'Europe/Moscow' });
  text += `<b>${index + 1}. 📋 ${item.json.title}</b>\n`;
  text += `├ 📅 Дата: <code>${date}</code>\n`;
  text += `└ 📂 Путь: <code>${item.json.file_path}</code>\n\n`;
});
return [{ json: { text } }];

try {
  const lines = ($input.first().json.stdout || '').trim().split('\n');
  const jsonLine = lines.reverse().find(l => l.startsWith('{'));
  const parsed = JSON.parse(jsonLine);
  return [{ json: parsed }];
} catch (e) {
  return [{ json: { error: e.message, raw: $input.first().json.stderr || $input.first().json.stdout } }];
}

